// â”€â”€ JobPulse â€” New Job Alert Email Builder â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Reads the current alert + run data, builds a premium branded HTML email,
// and returns { to, subject, html, count } for the next node (e.g. Send Email).

const alert = $('Loop Over Alerts').item.json;
const run = $json;

const jobs = Array.isArray(run.new_jobs) ? run.new_jobs : [];
const count = typeof run.count === 'number' ? run.count : jobs.length;

const BRAND = 'QuestAi';
const LOGO_URL = 'https://plain-apac-prod-public.komododecks.com/202609/25/Vks3Yyo4JP6b6VuUr1UW/image.png';
const INK = '#0f0f14';
const ACCENT = '#6366f1';
const ACCENT_2 = '#a855f7';
const APPLY_COLOR = '#10b981';
const CARD_BG = '#ffffff';
const PAGE_BG = '#f4f4f7';

const query = alert.query || 'your search';
const location = alert.location || '';
const email = alert.email || '';
const today = new Date().toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});

// â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const esc = (s) =>
  String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const pick = (obj, keys) => {
  for (const k of keys) {
    if (obj[k] != null && String(obj[k]).trim() !== '') return obj[k];
  }
  return '';
};

const initials = (name) =>
  esc(
    String(name || '?')
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map((w) => w[0])
      .join('')
      .toUpperCase()
  );

const metaPill = (label, val) => {
  if (val == null || String(val).trim() === '') return '';
  return (
    '<span style="display:inline-block;background:#f4f4f7;color:#4b5563;font-size:12px;' +
    'font-weight:600;padding:5px 11px;border-radius:8px;margin:0 6px 6px 0;">' +
    '<span style="color:#9ca3af;font-weight:500;">' + esc(label) + ':</span> ' + esc(val) +
    '</span>'
  );
};

// â”€â”€ Job cards â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const cards = jobs
  .map((j, idx) => {
    const title = pick(j, ['title', 'job_title', 'name']);
    const company = pick(j, ['company', 'company_name', 'employer']);
    const loc = pick(j, ['location', 'job_location', 'city']);
    const posted = pick(j, ['posted_at', 'posted_time', 'posted', 'date_posted']);
    const empType = pick(j, ['employment_type', 'job_type', 'type']);
    const workMode = pick(j, ['work_mode', 'workplace_type', 'remote']);
    const salary = pick(j, ['salary', 'salary_range', 'compensation']);
    const viewUrl = pick(j, ['job_url', 'url', 'link', 'view_url', 'share_link']);
    const applyUrl = pick(j, ['apply_url', 'application_url']);

    let highlights = j.highlights || j.skills || j.tags || [];
    if (typeof highlights === 'string') highlights = [highlights];

    const pills = [
      metaPill('Location', loc),
      metaPill('Posted', posted),
      metaPill('Type', empType),
      metaPill('Mode', workMode),
      metaPill('Salary', salary),
    ].join('');

    const chips =
      Array.isArray(highlights) && highlights.length
        ? '<div style="margin-top:10px;">' +
          highlights
            .map(
              (h) =>
                '<span style="display:inline-block;background:linear-gradient(135deg,#eef2ff,#f5f3ff);' +
                'color:' + ACCENT + ';font-size:11px;font-weight:700;padding:4px 10px;border-radius:9999px;' +
                'margin:0 6px 6px 0;border:1px solid #e0e7ff;">' + esc(h) + '</span>'
            )
            .join('') +
          '</div>'
        : '';

    let buttons = '<table role="presentation" cellpadding="0" cellspacing="0"><tr>';
    if (viewUrl) {
      buttons +=
        '<td style="padding-right:10px;"><a href="' + esc(viewUrl) + '" ' +
        'style="display:inline-block;background:#ffffff;color:' + INK + ';text-decoration:none;' +
        'font-size:13px;font-weight:700;padding:10px 18px;border-radius:9px;border:1.5px solid #e5e7eb;">' +
        'View Job</a></td>';
    }
    if (applyUrl) {
      buttons +=
        '<td><a href="' + esc(applyUrl) + '" ' +
        'style="display:inline-block;background:' + APPLY_COLOR + ';color:#ffffff;text-decoration:none;' +
        'font-size:13px;font-weight:700;padding:10px 18px;border-radius:9px;">Apply Now â†’</a></td>';
    }
    buttons += '</tr></table>';

    return (
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" ' +
      'style="background:' + CARD_BG + ';border-radius:16px;margin:0 0 14px 0;' +
      'border:1px solid #ececf1;box-shadow:0 1px 2px rgba(16,16,20,0.04);">' +
      '<tr><td style="padding:20px;">' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
      '<td width="44" style="vertical-align:top;padding-right:14px;">' +
      '<div style="width:44px;height:44px;border-radius:11px;background:linear-gradient(135deg,' + ACCENT + ',' + ACCENT_2 + ');' +
      'color:#ffffff;font-size:15px;font-weight:800;text-align:center;line-height:44px;">' +
      initials(company || title) + '</div>' +
      '</td>' +
      '<td style="vertical-align:top;">' +
      (idx === 0 && jobs.length > 1
        ? '<span style="display:inline-block;background:#111827;color:#ffffff;font-size:10px;font-weight:800;' +
          'letter-spacing:0.5px;padding:2px 8px;border-radius:6px;margin-bottom:6px;">JUST POSTED</span><br>'
        : '') +
      (title ? '<div style="font-size:16px;font-weight:800;color:' + INK + ';line-height:1.35;">' + esc(title) + '</div>' : '') +
      (company ? '<div style="font-size:13.5px;color:#6b7280;font-weight:600;margin-top:2px;">' + esc(company) + '</div>' : '') +
      '</td></tr></table>' +
      (pills ? '<div style="margin-top:12px;">' + pills + '</div>' : '') +
      chips +
      '<div style="margin-top:16px;">' + buttons + '</div>' +
      '</td></tr></table>'
    );
  })
  .join('');

const noJobsBlock = !jobs.length
  ? '<div style="text-align:center;color:#9ca3af;font-size:14px;padding:32px 0;">No job details were included in this run.</div>'
  : '';

// â”€â”€ Subject + meta summary â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const plural = count === 1 ? 'job' : 'jobs';
const subject = 'ðŸ”” ' + count + ' new ' + plural + ' for ' + query;

// â”€â”€ Full HTML email â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const html =
  '<!DOCTYPE html><html><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width, initial-scale=1"></head>' +
  '<body style="margin:0;padding:0;background:' + PAGE_BG + ';font-family:-apple-system,Segoe UI,Roboto,Arial,Helvetica,sans-serif;">' +
  '<div style="max-width:600px;margin:0 auto;padding:28px 16px;">' +

  // Header â€” logo + brand wordmark
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:18px;">' +
  '<tr><td style="text-align:center;padding-bottom:6px;">' +
  '<img src="' + esc(LOGO_URL) + '" alt="' + esc(BRAND) + '" width="56" height="56" ' +
  'style="display:inline-block;border-radius:14px;box-shadow:0 4px 14px rgba(99,102,241,0.25);">' +
  '<div style="margin-top:10px;font-size:15px;font-weight:800;color:' + INK + ';letter-spacing:0.3px;">' +
  esc(BRAND) + '</div>' +
  '</td></tr>' +
  '</table>' +

  // Hero banner
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" ' +
  'style="background:linear-gradient(135deg,' + ACCENT + ' 0%,' + ACCENT_2 + ' 100%);border-radius:20px;margin-bottom:16px;">' +
  '<tr><td style="padding:26px 26px 24px;text-align:center;">' +
  '<div style="color:rgba(255,255,255,0.85);font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;">' +
  esc(today) + '</div>' +
  '<div style="color:#ffffff;font-size:26px;font-weight:800;line-height:1.25;">' +
  esc(count) + ' new ' + plural + '</div>' +
  '<div style="color:rgba(255,255,255,0.9);font-size:14.5px;font-weight:500;margin-top:4px;">' +
  'matching &quot;' + esc(query) + (location ? '&quot; near ' + esc(location) : '&quot;') + '</div>' +
  '</td></tr></table>' +

  // Job cards
  cards +
  noJobsBlock +

  // Footer
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px;">' +
  '<tr><td style="text-align:center;padding:18px 10px 4px;">' +
  '<div style="font-size:12px;color:#9ca3af;line-height:1.6;">' +
  'Sent to ' + (email ? esc(email) : 'you') + ' by ' + esc(BRAND) + ' because you subscribed to job alerts for &quot;' + esc(query) + '&quot;.' +
  '</div>' +
  '</td></tr></table>' +

  '</div></body></html>';

return [{ json: { to: email, subject: subject, html: html, count: count } }];
